const raw = String($json.data ?? '');

// Deterministic cleanup: works for .vtt, .srt, Meet doc exports and plain text.
let t = raw.replace(/^WEBVTT.*$/m, '');
t = t.replace(/^\d+\s*$/gm, '');                 // srt cue indexes
t = t.replace(/^.*-->.*$/gm, '');                // timestamp lines
t = t.replace(/<[^>]+>/g, '');                   // vtt/html tags
t = t.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();

const words = t.split(/\s+/).filter(Boolean).length;
const speakers = [...new Set(
  [...t.matchAll(/^([A-Z][\w .'-]{1,30}):/gm)].map(m => m[1].trim())
)].slice(0, 20);

const meta = $('When Transcript Arrives in Drive').first().json;
const fileName = String(meta.name || 'meeting').replace(/\.[a-z0-9]+$/i, '');

return [{ json: {
  fileName,
  transcript: t.slice(0, 60000),
  words,
  speakers,
  tooShort: words < 100,
} }];

const src = $('Sanitize Transcript Text').first().json;

let s = String($input.first().json.text ?? '').trim()
  .replace(/^```(?:json)?/i, '').replace(/```\s*$/, '').trim();
const a = s.indexOf('{'), b = s.lastIndexOf('}');
if (a === -1 || b === -1) {
  throw new Error('The AI did not return a JSON object.');
}
const p = JSON.parse(s.slice(a, b + 1));

const arr = (x) => (Array.isArray(x) ? x : []);
const actions = arr(p.action_items)
  .filter(i => i && typeof i.task === 'string' && i.task.trim())
  .map(i => ({
    task: i.task.trim(),
    owner: i.owner && String(i.owner).trim() ? String(i.owner).trim() : null,
    due: i.due && /^\d{4}-\d{2}-\d{2}$/.test(String(i.due)) ? String(i.due) : null,
    priority: i.priority === 'high' ? 'high' : 'normal',
  }));

return [{ json: {
  fileName: src.fileName,
  words: src.words,
  speakers: src.speakers,
  title: String(p.meeting_title || src.fileName).trim(),
  summary: arr(p.summary).map(String).slice(0, 6),
  decisions: arr(p.decisions).map(String),
  actions,
  openQuestions: arr(p.open_questions).map(String),
  nothingFound: !actions.length && !arr(p.decisions).length,
} }];

const m = $input.first().json;
const today = new Date().toISOString().slice(0, 10);
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

const byOwner = {};
for (const a of m.actions) {
  const k = a.owner || 'Unassigned';
  (byOwner[k] = byOwner[k] || []).push(a);
}

const actionRows = Object.entries(byOwner).map(([owner, items]) => items.map((a, i) => `
  <tr style="border-bottom:1px solid #d8dee4">
    ${i === 0 ? `<td style="padding:6px 10px;font-weight:600;vertical-align:top" rowspan="${items.length}">${esc(owner)}</td>` : ''}
    <td style="padding:6px 10px">${a.priority === 'high' ? '🔴 ' : ''}${esc(a.task)}</td>
    <td style="padding:6px 10px;white-space:nowrap;color:#57606a">${a.due || '—'}</td>
  </tr>`).join('')).join('');

const section = (title, items) => items.length
  ? `<h2 style="font-size:14px;margin:16px 0 4px;text-transform:uppercase;color:#57606a">${title}</h2>
     <ul style="margin:4px 0;padding-left:20px">${items.map(i => `<li style="margin:3px 0">${esc(i)}</li>`).join('')}</ul>`
  : '';

const html = `<!doctype html><html><body style="margin:0;padding:0;background:#f6f8fa">
<div style="max-width:640px;margin:0 auto;padding:20px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#24292f">
  <div style="background:#fff;border:1px solid #d8dee4;border-radius:10px;padding:20px">
    <h1 style="font-size:18px;margin:0 0 2px">📋 ${esc(m.title)}</h1>
    <div style="font-size:12.5px;color:#57606a;margin-bottom:10px">${today} · ${m.speakers.length ? esc(m.speakers.join(', ')) + ' · ' : ''}${m.words.toLocaleString('en-US')} words</div>
    ${section('Summary', m.summary)}
    ${section('Decisions', m.decisions)}
    ${m.actions.length ? `<h2 style="font-size:14px;margin:16px 0 4px;text-transform:uppercase;color:#57606a">Action items</h2>
    <table style="width:100%;border-collapse:collapse;font-size:13.5px">
      <tr style="text-align:left;color:#57606a;font-size:11.5px;text-transform:uppercase">
        <th style="padding:4px 10px">Owner</th><th style="padding:4px 10px">Task</th><th style="padding:4px 10px">Due</th>
      </tr>${actionRows}</table>` : ''}
    ${section('Open questions', m.openQuestions)}
    ${m.nothingFound ? '<div style="background:#fff8c5;border:1px solid #d4a72c;border-radius:8px;padding:10px 14px;margin-top:12px">⚠ No clear decisions or action items were found — worth a manual look at the transcript.</div>' : ''}
    <div style="font-size:11.5px;color:#8b949e;margin-top:16px">Generated from "${esc(m.fileName)}" — review before sending.</div>
  </div>
</div></body></html>`;

const high = m.actions.filter(a => a.priority === 'high').length;
const tgList = m.actions.slice(0, 6)
  .map(a => `• ${a.task}${a.owner ? ' — ' + a.owner : ''}${a.due ? ' (' + a.due + ')' : ''}`)
  .join('\n');
const tg = `📋 ${m.title}\n${m.actions.length} action item${m.actions.length === 1 ? '' : 's'}${high ? ` (${high} high)` : ''}, ${m.decisions.length} decision${m.decisions.length === 1 ? '' : 's'}\n\n${tgList}${m.actions.length > 6 ? `\n…and ${m.actions.length - 6} more` : ''}${m.nothingFound ? '⚠ Nothing clearly actionable found — check the transcript.' : ''}\n\nFollow-up draft is in your Gmail — review and send.`;

return [{ json: {
  ...m, date: today, html, tg,
  subject: `Minutes & actions: ${m.title} (${today})`,
} }];

const m = $('Compile Minutes and Drafts').first().json;
return m.actions.map(a => ({ json: {
  Date: m.date,
  Meeting: m.title,
  Task: a.task,
  Owner: a.owner || '',
  Due: a.due || '',
  Priority: a.priority,
  Status: 'Open',
} }));
